graphql_query.query_structure:
query embedDocumentAndSimilaritySearch(
    $data: [EncodeDocumentPart], 
    $indices: [String], 
    $amount: Int, 
    $model: String!
) {
    encodeDocumentAndSimilaritySearch(
        data: $data
        indices: $indices
        amount: $amount
        model: $model
    ) {
        id
        score
        index
        document {
            title
            url
            PatspecterEmbedding
        }
    }
}
